// Separation routes: which MVSEP model and options Aurora uses for each stem, and how each result is checked.
// The choices come from 50 measured test splits on clips mixed from true stems (2026-10-02); the evidence
// line on each route is the score that chose it (SDR in dB against the true stem; second-brain
// plans/2026-10-02-aurora-splitter-mvsep-research/stem-map.md). Pure data, shared by the app's main process,
// the renderer (labels, cost) and aurora-mcp (a byte-identical copy; tools/sync-separation-to-mcp.mjs).

export type RouteOptionName = 'add_opt1' | 'add_opt2' | 'add_opt3'

/** What a correct target sounds like next to what was left, measured without the true stems:
 *  percussive = more transient than the rest; low = more energy under 150 Hz than the rest;
 *  vocal = less energy under 150 Hz than the rest; none = no cheap test separates it. */
export type ContentFamily = 'percussive' | 'low' | 'vocal' | 'none'

/** How clean the measured result was (SDR against the true stem, 2026-10-02): good = 9 dB or more;
 *  fair = 5 to 9; rough = under 5 on the material it is for (orchestral sections overlap); untested = no
 *  measurement yet. Shown next to each part before a paid run. */
export type RouteQuality = 'good' | 'fair' | 'rough' | 'untested'

export interface SeparationRoute {
  /** Stable id: the MCP tools and the job log name routes by it. */
  id: string
  label: string
  sepType: number
  options: Partial<Record<RouteOptionName, string>>
  /** Aurora stem id → the exact MVSEP output key holding it. */
  delivers: Record<string, string>
  /** The checked target and what it is compared with. `complement` is an output key; without one the
   *  check compares the target with the input minus the target. */
  family: { target: string; complement?: string; family: ContentFamily }
  /** Outputs that must add back to a whole (another output, or the uploaded input). Each holds on every
   *  measured job of this route: one-model routes to about -150 dB, ensembles to -37 dB or better. */
  sums: { parts: string[]; whole: string | 'input' }[]
  /** The measured result that chose this route, or "not measured" with the research rank it rests on. */
  evidence: string
  quality: RouteQuality
}

const route = (r: SeparationRoute): SeparationRoute => r

