/** A one-instrument route. `fromPart` routes run MVSEP's "Extract from <family> part" mode (`add_opt2=1`) and
 *  return four files: the target, `other-<family>` (the rest of that family), `all-<family>` and `no-<family>`.
 *  Measured exact on real jobs (2026-10-02, Brass from the wind part, Choir from the vocals): target +
 *  other-<family> = all-<family> (-211 dB) and all-<family> + no-<family> = the input (-153 dB). The family test
 *  compares the target with the input minus the target. */
const instrument = (
  id: string,
  sepType: number,
  key: string,
  options: SeparationRoute['options'] = {},
  { fromPart, family = 'none' as ContentFamily }: { fromPart?: 'wind' | 'strings' | 'guitar'; family?: ContentFamily } = {}
): SeparationRoute =>
  route({
    id,
    label: id,
    sepType,
    options: fromPart ? { ...options, add_opt2: '1' } : options,
    delivers: { [id]: key },
    family: fromPart ? { target: key, family } : { target: key, complement: 'other', family },
    sums: fromPart
      ? [
          { parts: [key, `other-${fromPart}`], whole: `all-${fromPart}` },
          { parts: [`all-${fromPart}`, `no-${fromPart}`], whole: 'input' }
        ]
      : [{ parts: [key, 'other'], whole: 'input' }],
    evidence: 'Not measured; carried over from prism.',
    quality: 'untested'
  })

const fromWind = { fromPart: 'wind' as const }
const fromStrings = { fromPart: 'strings' as const }
const fromGuitar = { fromPart: 'guitar' as const }

